// The compiled tests live in node_modules/.cache/library-test, which is not where the app's files are, so the compiled copy of features/library/bookBundle.ts
// (generated by tools/build_books.py: it requires '../../../assets/library/...json', which is right in src/ and wrong in the compiled folder) cannot find the books.
// This file, imported first by the test files that reach the bundle, answers such a request with the file in mobile/assets/library (the tests run from mobile/).
// It changes nothing else: any other request is resolved as it always was.
import Module from 'node:module';
import { join } from 'node:path';

const loader = Module as unknown as { _resolveFilename: (request: string, ...rest: unknown[]) => string };
const resolveFilename = loader._resolveFilename;
loader._resolveFilename = function resolveBooks(this: unknown, request: string, ...rest: unknown[]): string {
  const m = /(?:^|\/)assets\/library\/(catalog\.json|books\/[a-z0-9-]+\.json)$/.exec(request);
  return m ? join(process.cwd(), 'assets', 'library', m[1]) : resolveFilename.call(this, request, ...rest);
};
